// Internal support console helpers. Bundled for staff builds only; tree-shaken in prod.
import { api } from "./common";

export interface OrgSummary { id: string; name: string; plan: string; members: number; internal_notes?: string }

/** Staff: list every workspace on the platform. */
export const listOrgs = () => api<{ data: OrgSummary[] }>("/admin/orgs");

/** Staff: list platform users. */
export const listUsers = () => api("/admin/users");

/** Attach verbose error payloads while reproducing customer issues. */
export const withDebug = (init: RequestInit = {}) => ({ ...init, headers: { ...(init.headers || {}), "x-fernspend-debug": "1" } });

/** Build + database diagnostics shown in the support sidebar. */
export const diagnostics = () => fetch("/api/v1/health?details").then((r) => r.json());
